def matrix_power(matrix, n):
    # Base case for matrix exponentiation
    if n == 0:
        return np.identity(len(matrix), dtype=int)
    elif n == 1:
        return matrix
    else:
        half_power = matrix_power(matrix, n // 2)
        full_power = np.dot(half_power, half_power)
